import { Accordion, AccordionItem, AccordionTrigger, AccordionContent } from "@nativecn/ui/components/accordion";

export default function App() {
  return (
    <Accordion type="single" collapsible>
      <AccordionItem value="item-1">
        <AccordionTrigger>Is it highly customizable?</AccordionTrigger>
        <AccordionContent>Yes! You own the component code. Modify files directly inside your project structure.</AccordionContent>
      </AccordionItem>
      <AccordionItem value="item-2">
        <AccordionTrigger>Are micro-animations supported?</AccordionTrigger>
        <AccordionContent>Fully integrated with spring physics via React Native Reanimated and Moti.</AccordionContent>
      </AccordionItem>
    </Accordion>
  );
}
